def validate(row):
    key = row.get("order_id")
    amount = row.get("amount")
    if not isinstance(key, str) or not key.strip() or type(amount) is not int or amount < 0:
        raise ValueError("invalid row")
    return key.strip(), amount
def summarize(rows):
    seen = set()
    report = {"orders":0,"revenue":0,"rejected":[],"duplicates":[]}
    for number, row in enumerate(rows, 1):
        try:
            key, amount = validate(row)
        except ValueError:
            report["rejected"].append(number)
            continue
        if key in seen:
            report["duplicates"].append(number)
            continue
        seen.add(key)
        report["orders"] += 1
        report["revenue"] += amount
    return report

