def make_segmenter(low, high):
    counts = {"low":0,"mid":0,"high":0}
    def classify(value):
        if type(value) is not int or value < 0:
            raise ValueError("invalid value")
        group = "low" if value < low else "mid" if value < high else "high"
        counts[group] += 1
        return group
    def stats():
        return counts.copy()
    return classify, stats
